#include <iostream>
#include <type_traits>

struct Good { ~Good() = default; };
struct NoDtor { ~NoDtor() = delete; };

int main() {
    bool a = std::is_destructible_v<int>;
    bool b = std::is_destructible_v<Good>;
    bool c = std::is_destructible_v<NoDtor>;
    std::cout << std::boolalpha << a << b << c;
}
